import AppKitCore
import Testing

struct ClipCapturePolicyTests {
    private let text = "public.utf8-plain-text"

    @Test(arguments: ["org.nspasteboard.ConcealedType", "org.nspasteboard.TransientType", "com.agilebits.onepassword"])
    func neverKeepsAPrivateCopy(marker: String) {
        #expect(!ClipCapturePolicy().allows(types: [text, marker]))
        #expect(!ClipCapturePolicy(keepsAutoGenerated: true).allows(types: [text, marker]))
    }

    @Test func refusesAutoGeneratedCopiesByDefault() {
        #expect(!ClipCapturePolicy().allows(types: [text, "org.nspasteboard.AutoGeneratedType"]))
    }

    @Test func keepsAutoGeneratedCopiesOnRequest() {
        let policy = ClipCapturePolicy(keepsAutoGenerated: true)
        #expect(policy.allows(types: [text, "org.nspasteboard.AutoGeneratedType"]))
    }

    @Test func keepsAnOrdinaryCopy() {
        #expect(ClipCapturePolicy().allows(types: [text]))
    }
}
